/* UI adapters; no timers that replace an open conversation. */
(function(){
const A=TPDialogueAudit,D=TPDialogueData;
let archiveMode=false;const campaignRenderer=renderCase;
renderCase=function(){return archiveMode?window.TPLegacyRPG.render():campaignRenderer()};
window.openArchiveCase=function(id){archiveMode=true;window.TPLegacyRPG.open(id)};
window.openArchiveMenu=function(){openModal('進階查核短篇案卷',`<h2>21個主題，63條事實時間線</h2><p>這些是精簡概念副本，常規金額為給定教學輸入。與第一季完整故事、居民街談及BAPA資料分開保存；可自由選題。</p><div class="season-journal">${mysteries.map(c=>`<button data-archive-case="${c.id}"><b>${c.icon} ${safe(c.title)}</b><p>${safe(D.topics[c.id].focus)}</p></button>`).join('')}</div>`);document.querySelectorAll('[data-archive-case]').forEach(b=>b.onclick=()=>window.openArchiveCase(b.dataset.archiveCase))};
const archiveEntry=document.createElement('button');archiveEntry.className='mist-entry';archiveEntry.id='tp-archive-entry';archiveEntry.innerHTML='<span>📚</span><div><b>進階查核短篇案卷</b><small>21主題・正式預約・手動追問・三條事實時間線</small></div><em>自由選題 ↗</em>';archiveEntry.onclick=window.openArchiveMenu;document.querySelector('.explorer').insertAdjacentElement('afterend',archiveEntry);

window.TPDialogueRich=t=>safe(t).replace(/\[\[([^\]]+)\]\]/g,'<strong class="tp-evidence-key">$1</strong>').replaceAll('\n','<br>');
const originalPerson=personPanel;
personPanel=function(c,s,r,n){const html=originalPerson(c,s,r,n);if(!TPRPG.available(r,n.id)||n.id==='staff'&&!r.interviews.chief?.topics.includes('decision'))return html;const d=D.topics[c.id];return html+`<div class="professional-followup"><p><b>本案受訪職務：${safe(n.role)}</b> · ${safe(D.roles[n.id].title)}。本案人物的證言僅限這份案卷與目前時間線，不沿用島民街談。</p><p class="sim-fine">手動追問會依本案主題、角色及已取得資料回答；未記載內容會保留待查。這是多支線腳本，沒有連線生成式AI。</p><form id="case-free-question"><label>向本案受訪人手動追問<textarea id="case-free-text" maxlength="400" rows="2" placeholder="${safe(d.ask)}"></textarea></label><button class="choice" type="submit">提出具體追問 →</button></form><div class="case-domain-questions">${[[d.ask,'具體事件'],['本案有哪些最強反證？','檢驗另一解釋'],['哪個方法最可靠，適用哪段TPG？','方法與規範']].map(([q,l])=>`<button type="button" data-deep-question="${safe(q)}">${l}</button>`).join('')}</div></div>`};
const originalOpening=opening;
opening=function(c,s,n){const d=D.topics[c.id],w=c.worlds[s.universe],role=D.roles[n.id];return d?'【本案 '+n.role+'】'+role.known+'\n今天先查：'+d.focus+'\n這是本時間線交易起點：'+w.clues[0]+'\n你可以問我：'+d.ask:originalOpening(c,s,n)};
const oldAsk=askQuestion;
askQuestion=function(c,s,r,n,q,text){if(!A||!D.topics[c.id])return oldAsk(c,s,r,n,q,text);if(!TPRPG.available(r,n.id))return;const w=c.worlds[s.universe];r.interviews[n.id]??={topics:[],history:[{who:'npc',text:opening(c,s,n)}]};const v=r.interviews[n.id],query=q==='free'?text:({open:'請說明你親自參與的工作流程',decision:D.topics[c.id].ask,example:'哪些原始資料能證明本案具體事件？',capacity:'事前財務能力與帳務要核對哪些資料？',counter:'本案最強反證與另一種解釋？',cross:'出示決策紀錄，比對剛才說法',accuse:'你們全部都是虛假安排，對不對？',repair:'收回指控，重新表述具體問題',finish:'整理訪談結論'}[q]||text),result=A.caseReply(c,w,n.id,query,{docs:r.docs,seen:v.topics,turn:v.history.length,count:(v.replyCounts?.[A.kind(query)+'|'+[...r.docs].sort().join(',')]||0)});v.replyCounts??={};const memo=A.kind(query)+'|'+[...r.docs].sort().join(',');if(!result.skip)v.replyCounts[memo]=(v.replyCounts[memo]||0)+1;if(result.skip){toast(result.text);return}let topic=result.action;if(q==='example'&&topic==='records')topic='example';if(q==='capacity'&&topic==='records')topic='capacity';if(q==='open')topic='open';if(q==='free'&&result.action==='open')topic='clarify';if(result.action==='accuse')v.needsRepair=true;if(result.action==='repair')v.needsRepair=false;if(topic==='cross')v.discrepancy=true;if(!v.topics.includes(topic))v.topics.push(topic);v.history.push({who:'player',text:String(text).slice(0,400)},{who:'npc',text:result.text+'\n【來源】'+(result.sources.join('；')||'訪談程序／職務界線，未新增證據')});syncClues(s,r);saveWorld();renderCase()};
const originalWire=wireInterview;
wireInterview=function(c,s,r){originalWire(c,s,r);const n=witnesses(c).find(x=>x.id===r.npc);if(!n)return;const form=$('#case-free-question');if(form)form.onsubmit=e=>{e.preventDefault();const text=$('#case-free-text').value.trim();if(text)askQuestion(c,s,r,n,'free',text)};document.querySelectorAll('[data-deep-question]').forEach(b=>b.onclick=()=>askQuestion(c,s,r,n,'free',b.dataset.deepQuestion));document.querySelectorAll('.speech-bubble p').forEach(el=>el.innerHTML=window.TPDialogueRich(el.textContent));};
const oldRead=readDoc;
readDoc=function(c,s,r,k){const d=D.topics[c.id],html=oldRead(c,s,r,k);if(!d)return html;return html+`<div class="record-limits"><b>這份卡片能證明到哪裡？</b><p>這是短篇案卷摘錄，只有原文列出的事實。尚未提供完整原始附件、採樣程序或估值底稿；不能將摘要等同真實查核已驗證。</p><p>本案補核方向：${safe(d.docs.join('；'))}。</p><p>規範座標：${safe(d.refs)}。</p></div>`};
const oldPosition=positionView;
positionView=function(c,s,r){const d=D.topics[c.id];return oldPosition(c,s,r)+(d?`<details class="record-limits"><summary>本案方法、風險與查核限制</summary><p>${safe(d.method)}</p><p>${safe(d.pitfall)}</p><p>${safe(d.refs)}</p><p>本副本的「可靠報酬」數值為給定教學輸入，沒有完整可比資料時不宣稱你已自行完成常規報酬測定；仍可選補查。</p></details>`:'')};
const oldStep=openCampaignStep;
openCampaignStep=function(){archiveMode=false;oldStep();const e=seasonEpisode(),r=seasonRecord(),s=currentStep();if(s.kind!=='talk'||r.complete)return;const target=$('.authored-dialogue');if(!target)return;target.insertAdjacentHTML('beforeend',`<section class="professional-followup"><h3>帶著證據手動追問</h3><p class="sim-fine">只引用目前證據袋與本段已說出的話；不提前解鎖文件，不冒充受訪人知道全部案情。自由追問不取代主線需要的具體問話，也不計分。</p><form id="campaign-free-question"><label>向${safe(s.speaker)}手動追問<textarea id="campaign-free-text" maxlength="400" rows="2" placeholder="例如：這份已取得的文件，能證明誰決定、誰只是執行？"></textarea></label><button type="submit" class="choice">記下追問 →</button></form><div id="campaign-free-replies" aria-live="polite"></div></section>`);$('#campaign-free-question').onsubmit=event=>{event.preventDefault();const el=$('#campaign-free-text'),q=el.value.trim();if(!q)return;const answer=A.campaignReply(e,s,r,q),d=dialogueState(r,r.step,s);if(answer.skip){$('#campaign-free-replies').textContent=answer.text;return}d.history.push({speaker:'你',text:q},{speaker:s.speaker,text:answer.text+(answer.sources.length?'\n（依據：'+answer.sources.join('、')+'）':'')});saveSeason();$('#campaign-free-replies').insertAdjacentHTML('beforeend',`<div class="authored-line your-line"><small>你</small><p>${safe(q)}</p></div><div class="authored-line"><small>${safe(s.speaker)}／文據核對</small><p>${TPDialogueRich(answer.text)}</p><small>${safe(answer.sources.join('、')||'未新增證據')}</small></div>`);el.value='';};};
const styles=document.createElement('style');styles.textContent='.professional-followup,.record-limits{padding:20px;border:1px solid #a8b8a0;border-radius:16px;margin-top:20px;background:#f5f4e7}.professional-followup textarea{display:block;width:100%;box-sizing:border-box;min-height:76px;resize:vertical;margin:10px 0;padding:12px;border:1px solid #8daba0;border-radius:10px;background:#fffef5;color:#264d4b}.case-domain-questions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.tp-evidence-key{color:#a54a25;background:#fce5bb;font-weight:800;padding:0 3px}.record-limits p{line-height:1.9}.professional-followup form button{min-height:44px}';document.head.append(styles);
})();
